// The Materials pack's tables (ARCHITECTURE §12.2): the client's catalog, what each vendor calls an
// item (aliases), every matching decision, and price observations. Same tenancy rules as the
// platform's (CLAUDE.md invariant 1): every table has tenant_id, forced RLS on app.tenant_ids, and
// composite foreign keys (id, tenant_id) so a row can only point at the same client's rows.
//
// Migration 0032 (docs/plan.md §1.63) creates them (generated by drizzle-kit from this file, which the db package's
// drizzle config lists, plus hand-written SQL for the grants, RLS, the item_alias expression unique
// index and the pack-ownership comments). Migration 0033 (P-5, §1.67) adds purchase requests and
// quotes, and lets a price come from a QuickBooks bill line. This file imports only drizzle-orm and
// the platform's schema at runtime, so drizzle-kit can load it.

import {
  agentVersion,
  appUser,
  contact,
  docLine,
  document,
  rawRecord,
  run,
  tenant,
  transaction,
  vendor,
} from "@countersign/db";
import { type SQL, sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
  vector,
} from "drizzle-orm/pg-core";

// ── Allowed values ───────────────────────────────────────────────────────────────────────────────

// DECISION: five categories, one per parser (ARCHITECTURE §12.3), plus `other`. Mouldings and
// edgebanding share a category and tell themselves apart by the key attribute `kind`, as do
// finishes and adhesives.
export const CATEGORIES = [
  "sheet_goods",
  "hardwood",
  "mouldings",
  "hardware",
  "finishes",
  "other",
] as const;
export type Category = (typeof CATEGORIES)[number];

/** The unit a category's prices are compared in (invariant 7: never across different units). */
export const STANDARD_UOMS = [
  "sheet",
  "board_foot",
  "linear_foot",
  "each",
  "gallon",
  "quart",
] as const;
export type StandardUom = (typeof STANDARD_UOMS)[number];

export const ALIAS_SOURCES = ["auto", "human"] as const;
export const MATCH_DECISIONS = ["matched", "new_item", "unsure"] as const;
export const MATCH_METHODS = ["alias", "rules", "llm", "human"] as const;
export type MatchDecision = (typeof MATCH_DECISIONS)[number];
export type MatchMethod = (typeof MATCH_METHODS)[number];

function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(", "))})`;
}

const id = () => uuid("id").primaryKey().default(sql`uuid_generate_v7()`);
const tenantId = () =>
  uuid("tenant_id")
    .notNull()
    .references(() => tenant.id);
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
/** Money and quantities: numeric(14,4), a string in TypeScript (invariant 6). */
const decimal = (name: string) => numeric(name, { precision: 14, scale: 4 });

/** One thing the client buys, as the catalog knows it. */
export const catalogItem = pgTable(
  "catalog_item",
  {
    id: id(),
    tenantId: tenantId(),
    category: text("category").$type<Category>().notNull(),
    canonicalName: text("canonical_name").notNull(),
    /** Parsed attributes (thickness, size, species, grade, brand, model, …). */
    attributes: jsonb("attributes").$type<Record<string, unknown>>().notNull().default({}),
    standardUom: text("standard_uom").$type<StandardUom>().notNull(),
    // DECISION: the category plus every key attribute, in a fixed order, when all are known
    // (null otherwise). A live item's signature is unique per client, so two runs creating the
    // same item at once end with one row.
    keySignature: text("key_signature"),
    embedding: vector("embedding", { dimensions: 1024 }),
    // DECISION: `created_by` (ARCHITECTURE §12.2) is two typed columns, so each has a foreign key
    // and an agent's creation records its agent_version_id (invariant 10). Neither for imports.
    createdByAgentVersionId: uuid("created_by_agent_version_id").references(() => agentVersion.id),
    createdByUserId: uuid("created_by_user_id").references(() => appUser.id),
    mergedIntoId: uuid("merged_into_id"),
    createdAt: createdAt(),
    ext: jsonb("ext").$type<Record<string, unknown>>().notNull().default({}),
  },
  (t) => [
    unique("catalog_item_id_tenant_key").on(t.id, t.tenantId),
    foreignKey({
      name: "catalog_item_merged_into_fk",
      columns: [t.mergedIntoId, t.tenantId],
      foreignColumns: [t.id, t.tenantId],
    }),
    check("catalog_item_category_check", oneOf(t.category, CATEGORIES)),
    check("catalog_item_standard_uom_check", oneOf(t.standardUom, STANDARD_UOMS)),
    check("catalog_item_not_merged_into_self", sql`${t.mergedIntoId} is distinct from ${t.id}`),
    check(
      "catalog_item_created_by_check",
      sql`num_nonnulls(${t.createdByAgentVersionId}, ${t.createdByUserId}) <= 1`,
    ),
    uniqueIndex("catalog_item_key_signature_key")
      .on(t.tenantId, t.keySignature)
      .where(sql`${t.keySignature} is not null and ${t.mergedIntoId} is null`),
    index("catalog_item_category_idx").on(t.tenantId, t.category),
    // Candidates (ARCHITECTURE §12.3 step 4): equal key attributes by containment, then trigrams.
    index("catalog_item_attributes_idx").using("gin", t.attributes.op("jsonb_path_ops")),
    index("catalog_item_name_trgm_idx").using("gin", t.canonicalName.op("gin_trgm_ops")),
  ],
);

/**
 * What a vendor calls a catalog item: by its SKU, or by the hash of its normalized description.
 * Unique per (client, vendor, sku, hash) through an expression index in migration 0032.
 */
export const itemAlias = pgTable(
  "item_alias",
  {
    id: id(),
    tenantId: tenantId(),
    vendorId: uuid("vendor_id").notNull(),
    vendorSku: text("vendor_sku"),
    /** sha256 (hex) of the normalized description. */
    descriptionHash: text("description_hash"),
    /** The normalized description the hash was made from, for people and trigram search. */
    normalizedDescription: text("normalized_description"),
    catalogItemId: uuid("catalog_item_id").notNull(),
    source: text("source").$type<(typeof ALIAS_SOURCES)[number]>().notNull(),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    foreignKey({
      name: "item_alias_vendor_fk",
      columns: [t.vendorId, t.tenantId],
      foreignColumns: [vendor.id, vendor.tenantId],
    }),
    foreignKey({
      name: "item_alias_catalog_item_fk",
      columns: [t.catalogItemId, t.tenantId],
      foreignColumns: [catalogItem.id, catalogItem.tenantId],
    }),
    check("item_alias_source_check", oneOf(t.source, ALIAS_SOURCES)),
    check(
      "item_alias_key_check",
      sql`${t.vendorSku} is not null or ${t.descriptionHash} is not null`,
    ),
    check(
      "item_alias_description_hash_check",
      sql`${t.descriptionHash} is null or ${t.descriptionHash} ~ '^[0-9a-f]{64}$'`,
    ),
    index("item_alias_catalog_item_idx").on(t.tenantId, t.catalogItemId),
  ],
);

/** Every decision about one document line: the agent's, then a person's, newest last. */
export const itemMatch = pgTable(
  "item_match",
  {
    id: id(),
    tenantId: tenantId(),
    docLineId: uuid("doc_line_id").notNull(),
    catalogItemId: uuid("catalog_item_id"),
    decision: text("decision").$type<MatchDecision>().notNull(),
    confidence: numeric("confidence", { precision: 4, scale: 3 }).notNull(),
    method: text("method").$type<MatchMethod>().notNull(),
    /** The attribute the decision turned on (e.g. `thickness`), when one did. */
    hingeAttribute: text("hinge_attribute"),
    /** The candidates considered: ids, names, scores, why each was or wasn't taken. */
    candidates: jsonb("candidates").$type<unknown[]>().notNull().default([]),
    // DECISION: `decided_by` (agent_version_id or user_id) is two typed columns with foreign keys;
    // exactly one is set.
    agentVersionId: uuid("agent_version_id").references(() => agentVersion.id),
    decidedByUserId: uuid("decided_by_user_id").references(() => appUser.id),
    decidedAt: timestamp("decided_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    foreignKey({
      name: "item_match_doc_line_fk",
      columns: [t.docLineId, t.tenantId],
      foreignColumns: [docLine.id, docLine.tenantId],
    }),
    foreignKey({
      name: "item_match_catalog_item_fk",
      columns: [t.catalogItemId, t.tenantId],
      foreignColumns: [catalogItem.id, catalogItem.tenantId],
    }),
    check("item_match_decision_check", oneOf(t.decision, MATCH_DECISIONS)),
    check("item_match_method_check", oneOf(t.method, MATCH_METHODS)),
    check("item_match_item_check", sql`${t.decision} = 'unsure' or ${t.catalogItemId} is not null`),
    check("item_match_confidence_check", sql`${t.confidence} between 0 and 1`),
    check(
      "item_match_decided_by_check",
      sql`num_nonnulls(${t.agentVersionId}, ${t.decidedByUserId}) = 1`,
    ),
    index("item_match_doc_line_idx").on(t.tenantId, t.docLineId, t.decidedAt),
    index("item_match_catalog_item_idx").on(t.tenantId, t.catalogItemId),
  ],
);

/** A price paid for a catalog item, in its standard unit (ARCHITECTURE §12.4; written by M8b). */
export const priceObservation = pgTable(
  "price_observation",
  {
    id: id(),
    tenantId: tenantId(),
    catalogItemId: uuid("catalog_item_id").notNull(),
    vendorId: uuid("vendor_id").notNull(),
    observedOn: date("observed_on").notNull(),
    unitPriceStd: decimal("unit_price_std").notNull(),
    qtyStd: decimal("qty_std").notNull(),
    standardUom: text("standard_uom").$type<StandardUom>().notNull(),
    currency: text("currency").notNull().default("USD"),
    docLineId: uuid("doc_line_id"),
    transactionId: uuid("transaction_id"),
    agentVersionId: uuid("agent_version_id").references(() => agentVersion.id),
    ext: jsonb("ext").$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
    // P-5 (migration 0033): a price can also come from a synced QuickBooks bill line: the raw
    // record (the bill's version it was read from) and the line's id inside it.
    rawRecordId: uuid("raw_record_id"),
    rawLineId: text("raw_line_id"),
  },
  (t) => [
    foreignKey({
      name: "price_observation_catalog_item_fk",
      columns: [t.catalogItemId, t.tenantId],
      foreignColumns: [catalogItem.id, catalogItem.tenantId],
    }),
    foreignKey({
      name: "price_observation_vendor_fk",
      columns: [t.vendorId, t.tenantId],
      foreignColumns: [vendor.id, vendor.tenantId],
    }),
    foreignKey({
      name: "price_observation_doc_line_fk",
      columns: [t.docLineId, t.tenantId],
      foreignColumns: [docLine.id, docLine.tenantId],
    }),
    foreignKey({
      name: "price_observation_transaction_fk",
      columns: [t.transactionId, t.tenantId],
      foreignColumns: [transaction.id, transaction.tenantId],
    }),
    check("price_observation_standard_uom_check", oneOf(t.standardUom, STANDARD_UOMS)),
    // DECISION: one observation per document line, so recording prices twice adds nothing.
    unique("price_observation_doc_line_key").on(t.tenantId, t.docLineId),
    // P-5: the same for a bill line read from a raw record (`materials.backfill-from-bills`).
    foreignKey({
      name: "price_observation_raw_record_fk",
      columns: [t.rawRecordId, t.tenantId],
      foreignColumns: [rawRecord.id, rawRecord.tenantId],
    }),
    check(
      "price_observation_raw_line_check",
      sql`(${t.rawRecordId} is null) = (${t.rawLineId} is null)`,
    ),
    unique("price_observation_raw_line_key").on(t.tenantId, t.rawRecordId, t.rawLineId),
    index("price_observation_history_idx").on(
      t.tenantId,
      t.catalogItemId,
      t.vendorId,
      t.observedOn.desc(),
    ),
  ],
);

// ── P-5: purchase requests and quotes (migration 0033; docs/plan.md §1.67) ──────────────────────

/** Where a request to buy came in. `agent`: an agent opened it on its own (e.g. a reorder). */
export const REQUEST_CHANNELS = ["email", "sms", "whatsapp", "portal", "agent"] as const;
export type RequestChannel = (typeof REQUEST_CHANNELS)[number];

// DECISION: a request's status only moves forward along this list, except `cancelled`, which any
// status before `ordered` may move to. `closed` follows `ordered` (received, or nothing more to do).
export const REQUEST_STATUSES = [
  "open",
  "quoting",
  "quoted",
  "ordered",
  "cancelled",
  "closed",
] as const;
export type RequestStatus = (typeof REQUEST_STATUSES)[number];

export const FULFILLMENTS = ["delivery", "pickup"] as const;
export type Fulfillment = (typeof FULFILLMENTS)[number];

/** How a request line was tied to a catalog item: the vendor's alias, the rules, or a person. */
export const LINE_MATCH_METHODS = ["alias", "rules", "chosen"] as const;
export type LineMatchMethod = (typeof LINE_MATCH_METHODS)[number];

export const QUOTE_STATUSES = ["draft", "sent", "received", "declined", "expired"] as const;
export type QuoteStatus = (typeof QUOTE_STATUSES)[number];

export const QUOTE_CHANNELS = ["email", "sms", "whatsapp", "phone", "portal", "other"] as const;
export type QuoteChannel = (typeof QUOTE_CHANNELS)[number];

/** A request to buy materials: who asked, how, for when, and the order once placed. */
export const purchaseRequest = pgTable(
  "purchase_request",
  {
    id: id(),
    tenantId: tenantId(),
    // DECISION: who asked is a contact (a person in the client's directory, by text or email) or
    // a user (signed in to the portal); at most one, neither when an agent opened it.
    requestedByContactId: uuid("requested_by_contact_id"),
    requestedByUserId: uuid("requested_by_user_id").references(() => appUser.id),
    channel: text("channel").$type<RequestChannel>().notNull(),
    /** The message the request came in, as the connector stored it. */
    rawRecordId: uuid("raw_record_id"),
    status: text("status").$type<RequestStatus>().notNull().default("open"),
    neededBy: date("needed_by"),
    fulfillment: text("fulfillment").$type<Fulfillment>(),
    /** Where to deliver, or who picks up and where. */
    deliverTo: text("deliver_to"),
    notes: text("notes"),
    /** The order once placed: the client tool it is in and its id there (e.g. a QuickBooks PO). */
    orderConnector: text("order_connector"),
    orderExternalId: text("order_external_id"),
    orderedAt: timestamp("ordered_at", { withTimezone: true }),
    runId: uuid("run_id"),
    agentVersionId: uuid("agent_version_id").references(() => agentVersion.id),
    ext: jsonb("ext").$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("purchase_request_id_tenant_key").on(t.id, t.tenantId),
    foreignKey({
      name: "purchase_request_contact_fk",
      columns: [t.requestedByContactId, t.tenantId],
      foreignColumns: [contact.id, contact.tenantId],
    }),
    foreignKey({
      name: "purchase_request_raw_record_fk",
      columns: [t.rawRecordId, t.tenantId],
      foreignColumns: [rawRecord.id, rawRecord.tenantId],
    }),
    foreignKey({
      name: "purchase_request_run_fk",
      columns: [t.runId, t.tenantId],
      foreignColumns: [run.id, run.tenantId],
    }),
    check("purchase_request_channel_check", oneOf(t.channel, REQUEST_CHANNELS)),
    check("purchase_request_status_check", oneOf(t.status, REQUEST_STATUSES)),
    check(
      "purchase_request_fulfillment_check",
      sql`${t.fulfillment} is null or ${oneOf(t.fulfillment, FULFILLMENTS)}`,
    ),
    check(
      "purchase_request_requested_by_check",
      sql`num_nonnulls(${t.requestedByContactId}, ${t.requestedByUserId}) <= 1`,
    ),
    check(
      "purchase_request_order_check",
      sql`(${t.orderConnector} is null) = (${t.orderExternalId} is null)`,
    ),
    index("purchase_request_tenant_idx").on(t.tenantId, t.status, t.createdAt),
  ],
);

/** One thing asked for, as asked, and the catalog item once it is known. */
export const purchaseRequestLine = pgTable(
  "purchase_request_line",
  {
    id: id(),
    tenantId: tenantId(),
    purchaseRequestId: uuid("purchase_request_id").notNull(),
    lineNo: integer("line_no").notNull(),
    /** Null until matched: deterministic matching, or a person's choice among the candidates. */
    catalogItemId: uuid("catalog_item_id"),
    description: text("description").notNull(),
    qty: decimal("qty").notNull(),
    /** The unit as asked ("sheets", "bf", "boxes"), not converted. */
    unit: text("unit"),
    notes: text("notes"),
    matchMethod: text("match_method").$type<LineMatchMethod>(),
    matchConfidence: numeric("match_confidence", { precision: 4, scale: 3 }),
    /** The catalog items it could be, when matching wasn't sure. */
    candidates: jsonb("candidates").$type<unknown[]>().notNull().default([]),
    createdAt: createdAt(),
  },
  (t) => [
    unique("purchase_request_line_id_tenant_key").on(t.id, t.tenantId),
    unique("purchase_request_line_no_key").on(t.purchaseRequestId, t.lineNo),
    foreignKey({
      name: "purchase_request_line_request_fk",
      columns: [t.purchaseRequestId, t.tenantId],
      foreignColumns: [purchaseRequest.id, purchaseRequest.tenantId],
    }),
    foreignKey({
      name: "purchase_request_line_catalog_item_fk",
      columns: [t.catalogItemId, t.tenantId],
      foreignColumns: [catalogItem.id, catalogItem.tenantId],
    }),
    check("purchase_request_line_qty_check", sql`${t.qty} > 0`),
    check(
      "purchase_request_line_match_method_check",
      sql`${t.matchMethod} is null or ${oneOf(t.matchMethod, LINE_MATCH_METHODS)}`,
    ),
    check(
      "purchase_request_line_matched_check",
      sql`(${t.catalogItemId} is null) = (${t.matchMethod} is null)`,
    ),
    index("purchase_request_line_catalog_item_idx").on(t.tenantId, t.catalogItemId),
  ],
);

/** A request for a quote (RFQ): one vendor, one purchase request. */
export const quoteRequest = pgTable(
  "quote_request",
  {
    id: id(),
    tenantId: tenantId(),
    purchaseRequestId: uuid("purchase_request_id").notNull(),
    vendorId: uuid("vendor_id").notNull(),
    status: text("status").$type<QuoteStatus>().notNull().default("draft"),
    sentAt: timestamp("sent_at", { withTimezone: true }),
    dueAt: timestamp("due_at", { withTimezone: true }),
    receivedAt: timestamp("received_at", { withTimezone: true }),
    /** How it was sent, and the sent message's id in that channel when there is one. */
    sentVia: text("sent_via").$type<QuoteChannel>(),
    sentRef: text("sent_ref"),
    /** What the answer came in: the message (raw record) or the document (a PDF quote). */
    answerRawRecordId: uuid("answer_raw_record_id"),
    answerDocumentId: uuid("answer_document_id"),
    currency: text("currency").notNull().default("USD"),
    notes: text("notes"),
    runId: uuid("run_id"),
    agentVersionId: uuid("agent_version_id").references(() => agentVersion.id),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("quote_request_id_tenant_key").on(t.id, t.tenantId),
    // DECISION: one RFQ per vendor for a request; asking the same vendor again finds it.
    unique("quote_request_vendor_key").on(t.purchaseRequestId, t.vendorId),
    foreignKey({
      name: "quote_request_request_fk",
      columns: [t.purchaseRequestId, t.tenantId],
      foreignColumns: [purchaseRequest.id, purchaseRequest.tenantId],
    }),
    foreignKey({
      name: "quote_request_vendor_fk",
      columns: [t.vendorId, t.tenantId],
      foreignColumns: [vendor.id, vendor.tenantId],
    }),
    foreignKey({
      name: "quote_request_answer_raw_record_fk",
      columns: [t.answerRawRecordId, t.tenantId],
      foreignColumns: [rawRecord.id, rawRecord.tenantId],
    }),
    foreignKey({
      name: "quote_request_answer_document_fk",
      columns: [t.answerDocumentId, t.tenantId],
      foreignColumns: [document.id, document.tenantId],
    }),
    foreignKey({
      name: "quote_request_run_fk",
      columns: [t.runId, t.tenantId],
      foreignColumns: [run.id, run.tenantId],
    }),
    check("quote_request_status_check", oneOf(t.status, QUOTE_STATUSES)),
    check(
      "quote_request_sent_via_check",
      sql`${t.sentVia} is null or ${oneOf(t.sentVia, QUOTE_CHANNELS)}`,
    ),
    index("quote_request_tenant_idx").on(t.tenantId, t.status, t.createdAt),
  ],
);

/**
 * A vendor's answer for one request line. DECISION: a quote is not a price observation: price
 * history stays what was paid; quotes live here and are compared here.
 */
export const quoteLine = pgTable(
  "quote_line",
  {
    id: id(),
    tenantId: tenantId(),
    quoteRequestId: uuid("quote_request_id").notNull(),
    purchaseRequestLineId: uuid("purchase_request_line_id").notNull(),
    catalogItemId: uuid("catalog_item_id"),
    /** As the vendor wrote it (data, never instructions: invariant 9). */
    description: text("description"),
    qty: decimal("qty"),
    unit: text("unit"),
    unitPrice: decimal("unit_price"),
    currency: text("currency").notNull().default("USD"),
    /** The price in the catalog item's standard unit, when a conversion rule exists; else null. */
    unitPriceStd: decimal("unit_price_std"),
    standardUom: text("standard_uom").$type<StandardUom>(),
    leadTimeDays: integer("lead_time_days"),
    available: boolean("available").notNull().default(true),
    notes: text("notes"),
    createdAt: createdAt(),
  },
  (t) => [
    unique("quote_line_id_tenant_key").on(t.id, t.tenantId),
    unique("quote_line_request_line_key").on(t.quoteRequestId, t.purchaseRequestLineId),
    foreignKey({
      name: "quote_line_quote_request_fk",
      columns: [t.quoteRequestId, t.tenantId],
      foreignColumns: [quoteRequest.id, quoteRequest.tenantId],
    }),
    foreignKey({
      name: "quote_line_request_line_fk",
      columns: [t.purchaseRequestLineId, t.tenantId],
      foreignColumns: [purchaseRequestLine.id, purchaseRequestLine.tenantId],
    }),
    foreignKey({
      name: "quote_line_catalog_item_fk",
      columns: [t.catalogItemId, t.tenantId],
      foreignColumns: [catalogItem.id, catalogItem.tenantId],
    }),
    check(
      "quote_line_standard_uom_check",
      sql`${t.standardUom} is null or ${oneOf(t.standardUom, STANDARD_UOMS)}`,
    ),
    check("quote_line_std_check", sql`${t.unitPriceStd} is null or ${t.standardUom} is not null`),
    check("quote_line_qty_check", sql`${t.qty} is null or ${t.qty} > 0`),
    check("quote_line_price_check", sql`${t.unitPrice} is null or ${t.unitPrice} >= 0`),
    check("quote_line_lead_time_check", sql`${t.leadTimeDays} is null or ${t.leadTimeDays} >= 0`),
  ],
);

/** The pack's tenant tables, in the order its RLS tests walk them. */
export const MATERIALS_TABLES = [
  "catalog_item",
  "item_alias",
  "item_match",
  "price_observation",
  // P-5 (0033)
  "purchase_request",
  "purchase_request_line",
  "quote_request",
  "quote_line",
] as const;
export type MaterialsTable = (typeof MATERIALS_TABLES)[number];
